    These are the fields `prepare_row` clips. Reported, never repaired: the fix for a clipped
    reference is a wider column or a corrected declared width, not reshaping the vendor's value.
    """
    widths = column_widths(settings)
    clipped = []
    for field, value in dict(record).items():
        width = widths.get(field)
        if not width:
            continue
        if len(as_text(value)) > int(width):
            clipped.append(field)
    return clipped


def suspect_fields(record, settings=None):
    """Declared fields whose value has a shape that will not join, mapped to why.

    Reported, never repaired. A reference carrying a stray `\\r` from the vendor's CSV, or padding
    from a fixed-width extract, fails against the master exactly like a clipped one does - silently,
    and as a non-match rather than an error. Trimming it here is not ours to do (the value is the
    vendor's identifier and the posting job's idempotency key), but storing it without saying so is
    how a whole quarter went wrong in OPS-4870. So the write path names it and moves on.
    """
    widths = column_widths(settings)
    suspect = {}
    for field, value in dict(record).items():
        if field not in widths:
            continue
        text = as_text(value)
        reasons = []
        if value is None:
            reasons.append("missing")
        elif not text:
            reasons.append("empty")
        if text and text != text.strip():
            reasons.append("edge_whitespace")
        if _CONTROL & set(text):
            reasons.append("control_chars")
        if value is not None and not isinstance(value, (str, bytes)):
            reasons.append("non_text")
        if reasons:
            suspect[field] = reasons
    return suspect


def prepare_row(record, settings=None):
    """Prepare one row: clip each text field to its declared column width."""
    widths = column_widths(settings)
    row = {}
    for field, value in dict(record).items():
        text = as_text(value)
        width = widths.get(field)
        row[field] = text[:int(width)] if width else text
    return row


def store_lines(records, sink, settings=None):
    """Write a batch in order. Returns one outcome record per line."""
    if settings is None:
        settings = load_settings()
    outcomes = []
    for record in records:
        row = prepare_row(record, settings)
        sink.write(row)
        outcomes.append({"line_id": record.get("line_id"), "outcome": "stored",
                         "vendor_reference": row.get("vendor_reference"),
                         "clipped": clipped_fields(record, settings)})
    return outcomes
